				if (!/^\s*["'`*_]?[A-Z`]/.test(line)) continue;
				const clipped = b.kind === "user" ? `[user] ${clipSentence(line, 150)}` : clipSentence(line, 150);
				if (!items.includes(clipped)) items.push(clipped);
				break;
			}
		}
	}

	return items.slice(0, 5);
